{
  "title": "Weak Signal or Real Evidence? A PM's Field Guide",
  "seriesTag": "Product Instincts",
  "brand": {
    "apply": false,
    "paper": "#EFE9DA",
    "ink": "#212B21",
    "accent": "#C08A28",
    "headline": "editorial",
    "body": "clean"
  },
  "slides": [
    {
      "title": "One customer complaint isn't a roadmap item",
      "body": "But three is starting to look like a pattern. The difference between noise and signal is testable — here's how to tell them apart.",
      "isCover": true
    },
    {
      "title": "The source problem",
      "body": "A signal from your loudest account, your CEO's friend, or last week's churn call is not representative. Note who said it before you note what they said.",
      "isCover": false
    },
    {
      "title": "The repetition test",
      "body": "Has this problem surfaced across three or more unrelated customers, in their own words, without you prompting it? If you had to ask a leading question, the clock resets.",
      "isCover": false
    },
    {
      "title": "The behavior gap test",
      "body": "Did they describe a pain, or did they build a workaround? Workarounds are evidence. Complaints without action are wishes. Look for what people already do, not what they say they want.",
      "isCover": false
    },
    {
      "title": "The specificity test",
      "body": "Vague signals sound like 'it's hard to collaborate.' Real evidence sounds like 'every Monday I export this to a spreadsheet because the tool can't do X.' Precision is a proxy for frequency.",
      "isCover": false
    },
    {
      "title": "The 'so what' test",
      "body": "Ask: if we solved this, what metric moves and by how much? If no one can answer, the signal hasn't been stress-tested. Evidence survives this question. Noise doesn't.",
      "isCover": false
    },
    {
      "title": "Run this test on one item in your backlog this week",
      "body": "Pick a ticket backed by customer feedback. Apply all four tests. If it fails two or more, move it to a watch list — not the roadmap. Share what you find with your team.",
      "isCover": true
    }
  ]
}
